873	func restoreResumeSessions(ctx context.Context, w, errW io.Writer, metadata *strategy.CheckpointInfo, force bool) ([]strategy.RestoredSession, error) {
874		checkpointID := metadata.CheckpointID
875		sessionID := metadata.SessionID
876	
877		// Resolve agent from checkpoint metadata (same as rewind)
878		ag, err := strategy.ResolveAgentForRewind(metadata.Agent)
879		if err != nil {
880			return nil, fmt.Errorf("failed to resolve agent: %w", err)
881		}
882	
883		// Initialize logging context with agent
884		logCtx := logging.WithAgent(logging.WithComponent(ctx, "resume"), ag.Name())
885	
886		logging.Debug(logCtx, "resume session started",
887			slog.String("checkpoint_id", checkpointID.String()),
888			slog.String("session_id", sessionID),
889		)
890	
891		// Get worktree root for session directory lookup
892		repoRoot, err := paths.WorktreeRoot(ctx)
893		if err != nil {
894			return nil, fmt.Errorf("failed to get worktree root: %w", err)
895		}
896	
897		sessionDir, err := ag.GetSessionDir(repoRoot)
898		if err != nil {
899			return nil, fmt.Errorf("failed to determine session directory: %w", err)
900		}
901	
902		// Create directory if it doesn't exist
903		if err := os.MkdirAll(sessionDir, 0o700); err != nil {
904			return nil, fmt.Errorf("failed to create session directory: %w", err)
905		}
906	
907		// Get strategy and restore sessions using full checkpoint data
908		strat := GetStrategy(ctx)
909	
910		// Use RestoreLogsOnly via LogsOnlyRestorer interface for multi-session support
911		// Create a logs-only rewind point with Agent populated (same as rewind)
912		point := strategy.RewindPoint{
913			IsLogsOnly:   true,
914			CheckpointID: checkpointID,
915			Agent:        metadata.Agent,
916		}
917	
918		sessions, restoreErr := strat.RestoreLogsOnly(ctx, w, errW, point, force)
919		if restoreErr != nil || len(sessions) == 0 {
920			// Fall back to single-session restore (e.g., old checkpoints without agent metadata)
921			session, ok, err := restoreSingleSession(ctx, w, ag, sessionID, checkpointID, repoRoot, force)
922			if err != nil || !ok {
923				return nil, err
924			}
925			return []strategy.RestoredSession{session}, nil
926		}
927	
928		logging.Debug(logCtx, "resume session completed",
929			slog.String("checkpoint_id", checkpointID.String()),
930			slog.Int("session_count", len(sessions)),
931		)
932	
933		return sessions, nil
